    ["<Assistant_Title1>The Chosen \"Person\"</>\n<Assistant_Title2>Achievement Category:</>Leisure-Fun\n<Assistant_Title2>Unlock Condition:</>Selected to become a phantom projection once"] = "<Assistant_Title1>The Chosen \"Person\"</>\n<Assistant_Title2>Achievement Category:</>Leisure-Fun\n<Assistant_Title2>Unlock Condition:</>Selected to become a phantom projection once",
